set-variable.value:
@{
    var settings = JObject.Parse((string)context.Variables["gatewayControlSettings"]);
    var operations = settings["tokenLimitOperationIds"] as JArray;
    var supported = !(bool)context.Variables["gatewayRateLimitExempt"] && operations != null && operations.Any(value => (string)value == context.Operation.Id);
    var decision = JObject.Parse((string)context.Variables["gatewayDecision"]);
    if ((string)decision["method"] != "user") { return supported; }
    if (!(bool)decision["allowed"] || !context.Variables.ContainsKey("gatewayEntraAuthenticationValidated")
        || !(bool)context.Variables["gatewayEntraAuthenticationValidated"]
        || !context.Variables.ContainsKey("gatewayEntraUserLimits")) { throw new Exception("Configured employee limits are required"); }
    var limits = JObject.Parse((string)context.Variables["gatewaySubscriptionProfile"]);
    if (!JToken.DeepEquals(limits, JObject.Parse((string)context.Variables["gatewayEntraUserLimits"]))
        || limits["tokensPerMinute"] == null || limits["tokenQuota"] == null) { throw new Exception("Configured employee limits are required"); }
    /* 明示nullは制限なし。利用者監査とnative usage logの設定には影響しません。 */
    return supported && (limits["tokensPerMinute"].Type != JTokenType.Null || limits["tokenQuota"].Type != JTokenType.Null);
  }

@{
      var decision = JObject.Parse((string)context.Variables["gatewayDecision"]);
      if ((string)decision["method"] == "user") {
        if (!(bool)decision["allowed"] || !context.Variables.ContainsKey("gatewayEntraAuthenticationValidated") || !(bool)context.Variables["gatewayEntraAuthenticationValidated"]) { throw new Exception("Verified employee is required"); }
        var user = JObject.Parse((string)context.Variables["gatewayUserAuthentication"]);
        var identity = (string)user["tenantId"] + ":" + (string)user["principalId"];
        if ((string)decision["callerId"] != "user:" + identity || (string)decision["allocationId"] != "user:" + identity
            || (string)user["callerId"] != "user:" + identity) { throw new Exception("Verified employee is required"); }
        return "core-tokens-v1:user:" + identity;
      }
      return "core-tokens-v1:" + context.Subscription.Id;
    }

@{
      var quota = JObject.Parse((string)context.Variables["gatewaySubscriptionProfile"])["tokenQuota"] as JObject;
      return quota == null ? 0 : (int)quota["tokens"];
    }

@{
      var quota = JObject.Parse((string)context.Variables["gatewaySubscriptionProfile"])["tokenQuota"] as JObject;
      return quota == null ? "Monthly" : (string)quota["period"];
    }
